@push('styles')
<style>
.tickets{max-width:1100px;margin:auto;padding:42px 0 75px}.ticketHead{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.ticketHead h1{font-size:32px;margin:5px 0;overflow-wrap:anywhere}.ticketRow{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:18px;align-items:center;padding:18px;border:1px solid var(--line);border-radius:12px;margin:10px 0}.ticketRow b,.ticketRow small{display:block;overflow-wrap:anywhere}.ticketRow small{color:#8da5bf;margin-top:5px}.conversation{display:grid;gap:14px}.message{padding:18px;border:1px solid var(--line);border-radius:12px;background:#081522;overflow-wrap:anywhere}.message.staff{border-left:3px solid #5aa4e6;background:#0d2033}.messageMeta{font-size:12px;color:#9ab2cd;margin-bottom:10px}.messageBody{white-space:pre-wrap;font-size:14px;line-height:1.7}.textarea{width:100%;min-height:160px;padding:14px;border-radius:10px;border:1px solid #294765;background:#06111d;color:#fff;resize:vertical}.ticketGrid{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:22px}.ticketFields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ticketTools{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.ticketTools .input{flex:1;min-width:150px}.ratingForm{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:16px}.ratingForm select{background:#06111d;color:#fff;border:1px solid #294765;padding:7px;border-radius:6px}.ticketNotice{padding:16px;border:1px solid #294765;border-radius:10px;margin:18px 0}.ticketPagination{margin-top:20px}.ticketPagination svg{max-width:22px;max-height:22px}.ticketPagination nav>div{margin:12px 0}.ticketPagination a,.ticketPagination span[aria-current]{display:inline-block;padding:6px 10px}.ticketBack{color:#9ab2cd;display:inline-block;margin-bottom:12px}.suggestedArticles a{display:block;padding:8px 0;color:#aad5ff}@media(max-width:760px){.tickets{padding:24px 0 50px}.ticketGrid,.ticketFields{grid-template-columns:1fr}.ticketRow{grid-template-columns:1fr;gap:8px}.ticketHead{align-items:flex-start;flex-direction:column}.ticketHead h1{font-size:26px}}
</style>
@endpush
